PROD-CORE.body:
import {readTable,bindFields,replaceTextAndImage,setPrintSize,writeProject,renderPng,renderPdf} from './engine.mjs';
export const importTable = path => readTable(path);
export const makeBatch = (template,rows) => rows.map(row => bindFields(template,row));
export const replaceRegion = (project,region,value) => replaceTextAndImage(project,region,value);
export const resize = (project,width,height,dpi) => setPrintSize(project,width,height,dpi);
export const saveProject = (project,path) => writeProject(project,path);
export const exportBatch = (projects,format,folder) => Promise.all(projects.map(p => format==='png'?renderPng(p,folder):renderPdf(p,folder)));
// 输出仍需人工核对文本、图片和打印尺寸。商城发布没有实现；上述制作链不调用searchImages。

